'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var dindexOfGreaterThanSorted = tryRequire( resolve( __dirname, './../lib/ndarray.native.js' ) );
var opts = {
	'skip': ( dindexOfGreaterThanSorted instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dindexOfGreaterThanSorted, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', opts, function test( t ) {
	t.strictEqual( dindexOfGreaterThanSorted.length, 5, 'has expected arity' );
	t.end();
});

tape( 'the function returns the index of the first element in a sorted strided array which is greater than a provided search element', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = dindexOfGreaterThanSorted( x.length, 1.0, x, 1, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function returns the index of the first element in a sorted strided array which is greater than a provided search element when the search element is not present in the strided array', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = dindexOfGreaterThanSorted( x.length, 1.5, x, 1, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if every indexed element in the array is less than or equal to the search element', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 2.0, 2.0, 2.0 ] );

	actual = dindexOfGreaterThanSorted( x.length, 2.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if a provided `N` parameter is less than or equal to zero', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 2.0, 3.0 ] );

	actual = dindexOfGreaterThanSorted( 0, 2.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dindexOfGreaterThanSorted( -1, 2.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if comparisons involve `NaN` values', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 0.0, 1.0 ] );

	actual = dindexOfGreaterThanSorted( 2, NaN, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	x = new Float64Array( [ NaN, NaN ] );

	actual = dindexOfGreaterThanSorted( 2, 0.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function treats `-0` and `+0` as equal', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 0.0 ] );

	actual = dindexOfGreaterThanSorted( 1, -0.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	x = new Float64Array( [ -0.0 ] );

	actual = dindexOfGreaterThanSorted( 1, 0.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		1.0, // 0
		9.0,
		2.0, // 1
		9.0,
		3.0  // 2
	]);

	actual = dindexOfGreaterThanSorted( 3, 2.0, x, 2, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative `x` stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		3.0, // 2
		9.0,
		2.0, // 1
		9.0,
		1.0  // 0
	]);

	actual = dindexOfGreaterThanSorted( 3, 1.0, x, -2, 4 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` offset', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		9.0,
		1.0, // 0
		9.0,
		2.0, // 1
		9.0,
		3.0  // 2
	]);

	actual = dindexOfGreaterThanSorted( 3, 2.0, x, 2, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		9.0,
		1.0, // 0
		9.0,
		2.0, // 1
		9.0,
		3.0  // 2
	]);

	actual = dindexOfGreaterThanSorted( 3, 2.0, x, 2, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function returns the index of the first element in a sorted strided array which is greater than a provided search element (descending order)', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ] );

	actual = dindexOfGreaterThanSorted( x.length, 2.0, x, 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns the index of the first element in a sorted strided array which is greater than a provided search element when the search element is not present in the strided array (descending order)', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ] );

	actual = dindexOfGreaterThanSorted( x.length, 1.5, x, 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if every indexed element in the array is less than or equal to the search element (descending order)', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 3.0, 2.0, 1.0 ] );

	actual = dindexOfGreaterThanSorted( x.length, 3.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride (descending order)', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		3.0, // 0
		9.0,
		2.0, // 1
		9.0,
		1.0  // 2
	]);

	actual = dindexOfGreaterThanSorted( 3, 2.0, x, 2, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative `x` stride (descending order)', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		1.0, // 2
		9.0,
		2.0, // 1
		9.0,
		3.0  // 0
	]);

	actual = dindexOfGreaterThanSorted( 3, 2.0, x, -2, 4 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` offset (descending order)', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		9.0,
		3.0, // 0
		9.0,
		2.0, // 1
		9.0,
		1.0  // 2
	]);

	actual = dindexOfGreaterThanSorted( 3, 2.0, x, 2, 1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});
